from io import StringIO
import zipfile

import six


class Loader(object):
    WORDS_TO_SKIP = 16

    def __init__(self):
        self.traces = []

    def read_from_file(self, file_path):
        if zipfile.is_zipfile(file_path):
            data = self._read_zip(file_path)
        else:
            data = self._read_txt(file_path)

        next(data)  # skip header

        for line in data:
            line_stripped = line.rstrip(';\n\r')
            line_as_ints = [int(word, 10) for word in line_stripped.split(',')]
            self.traces.append(line_as_ints)

        return self

    def _read_txt(self, file_path):
        with open(file_path) as fh:
            return StringIO(six.ensure_text(fh.read()))

    def _read_zip(self, file_path):
        archive = zipfile.ZipFile(file_path, 'r')
        file_name = archive.filelist[0].filename
        return StringIO(six.ensure_text(archive.read(file_name)))
